/* Script único, reaproveitado na Home e em paginaChrome. Consulta o DOM
   só dentro do callback assíncrono do fetch — evita depender da ordem
   entre a tag <script> e o <footer> no HTML. */
const SCRIPT_PRESENCA =
  '<script>(function(){' +
  'var KEY="ownews_sid";var sid=null;' +
  'try{sid=localStorage.getItem(KEY);}catch(e){}' +
  'if(!sid){try{sid=(window.crypto&&crypto.randomUUID)?crypto.randomUUID():("sid-"+Date.now()+"-"+Math.random().toString(36).slice(2));localStorage.setItem(KEY,sid);}catch(e){sid="sid-"+Date.now()+"-"+Math.random().toString(36).slice(2);}}' +
  'var timer=null;' +
  'function atualizar(dados){' +
  'var el=document.getElementById("leitoresOnline");if(!el)return;' +
  'if(dados&&typeof dados.online==="number"&&dados.online>0){' +
  'el.hidden=false;' +
  'el.textContent=dados.online===1?"1 leitor online agora":dados.online+" leitores online agora";' +
  '}else{el.hidden=true;}' +
  '}' +
  'function bater(){' +
  'fetch("/api/leitores/heartbeat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:sid})})' +
  '.then(function(r){if(!r.ok)throw new Error("presenca "+r.status);return r.json();})' +
  '.then(atualizar)' +
  '.catch(function(){var el=document.getElementById("leitoresOnline");if(el)el.hidden=true;});' +
  '}' +
  'function agendar(){if(timer)clearTimeout(timer);if(document.hidden)return;timer=setTimeout(function(){bater();agendar();},45000);}' +
  'document.addEventListener("visibilitychange",function(){if(document.hidden){if(timer)clearTimeout(timer);}else{bater();agendar();}});' +
  'bater();agendar();' +
  '})();</script>';

/* Contador real de visitas (rodapé) — 2026-09-17. Reaproveita o MESMO
   sessionId de localStorage ("ownews_sid") já usado em Presence/Pageview.
   Registra no máximo 1 "visita" por sessão por dia (dedupe feito no
   servidor, na Durable Object) e busca o total agregado (histórico, nunca
   decresce) para exibir no rodapé. Nunca expõe nada além do número final;
   se a chamada falhar, o span de destino simplesmente permanece oculto —
   não mostra "0 visitas" nem trava a página. */
const SCRIPT_VISITAS =
  '<script>(function(){' +
  'var KEY="ownews_sid";var sid=null;' +
  'try{sid=localStorage.getItem(KEY);}catch(e){}' +
  'if(!sid){try{sid=(window.crypto&&crypto.randomUUID)?crypto.randomUUID():("sid-"+Date.now()+"-"+Math.random().toString(36).slice(2));localStorage.setItem(KEY,sid);}catch(e){sid="sid-"+Date.now()+"-"+Math.random().toString(36).slice(2);}}' +
  'try{var utm=null;try{utm=new URLSearchParams(location.search).get("utm_source");}catch(e){}' +
  'fetch("/api/visita",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({sessionId:sid,path:location.pathname,ref:document.referrer||"",utm:utm||""})}).catch(function(){});}catch(e){}' +
  // Command Center: helper global único de eventos próprios — qualquer
  // página/script chama window.ownewsEvento("nome_do_evento") sem
  // duplicar a lógica de sessão/fetch em cada lugar (item "componente
  // único" também vale pra instrumentação, não só pro share).
  'window.ownewsEvento=function(nome){' +
  'try{fetch("/api/evento",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:nome,sessionId:sid,path:location.pathname})}).catch(function(){});}catch(e){}' +
  '};' +
  'function render(dados){' +
  'var el=document.getElementById("visitasTotal");if(!el)return;' +
  'if(!dados||typeof dados.total!=="number"||dados.total<=0)return;' +
  'var fmt;try{fmt=dados.total.toLocaleString("pt-BR");}catch(e){fmt=String(dados.total);}' +
  'el.textContent=fmt+(dados.total===1?" visita":" visitas")+(dados.desde?" desde "+dados.desde:"");' +
  'el.hidden=false;' +
  '}' +
  'fetch("/api/visitas-total").then(function(r){if(!r.ok)throw new Error("visitas "+r.status);return r.json();}).then(render).catch(function(){});' +
  '})();</script>';

/* Registro de pageview: fire-and-forget, nunca bloqueia a renderização
   da notícia e nunca quebra a página se a chamada falhar. Reaproveita o
   mesmo sessionId de localStorage usado em Presence (mesma chave
   "ownews_sid") — se Presence já rodou nesta página, o valor já existe;
   se não, é criado aqui do mesmo jeito, então os dois convergem. */
function scriptRegistrarPageview(articleId) {
  const idSeguro = JSON.stringify(String(articleId));
  return (
    '<script>(function(){' +
    'try{' +
    'var KEY="ownews_sid";var sid=null;' +
    'try{sid=localStorage.getItem(KEY);}catch(e){}' +
    'if(!sid){try{sid=(window.crypto&&crypto.randomUUID)?crypto.randomUUID():("sid-"+Date.now()+"-"+Math.random().toString(36).slice(2));localStorage.setItem(KEY,sid);}catch(e){sid="sid-"+Date.now()+"-"+Math.random().toString(36).slice(2);}}' +
    'fetch("/api/pageview",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({articleId:' + idSeguro + ',sessionId:sid})}).catch(function(){});' +
    '}catch(e){}' +
    '})();</script>'
  );
}

/* =========================================================================
   Monetização (Google AdSense) — arquitetura preparatória, INATIVA.
   =========================================================================
   ADS_ENABLED=false: nenhum script do Google é carregado, nenhum slot
   renderiza nada visível (adSlot() retorna string vazia). Não é feature
   flag de ambiente porque não há nada sensível aqui ainda — é um
   interruptor único e óbvio, trocado manualmente quando o dono decidir
   ativar de verdade (nunca por engano, nunca automaticamente).
   ADSENSE_CLIENT_ID fica null até haver uma conta AdSense real aprovada —
   nunca um ca-pub fictício, nunca um valor de teste. */
const ADS_ENABLED = false;
const ADSENSE_CLIENT_ID = null; // preencher só com o Publisher ID real, após aprovação

/* Componente central de anúncio. Enquanto ADS_ENABLED=false, é inerte:
   zero HTML, zero script, zero espaço reservado (sem CLS por não existir).
   Quando ativado (ADS_ENABLED=true + ADSENSE_CLIENT_ID configurado), passa
   a renderizar o slot real — a implementação do <ins class="adsbygoogle">
   e o carregamento do script oficial só entram nesse momento, como parte
   da ativação real (ver ADSENSE-READINESS.md), nunca antes. */
function adSlot(nome, formato) {
  if (!ADS_ENABLED || !ADSENSE_CLIENT_ID) return "";
  const fmt = formato || "auto";
  return (
    '<div class="ad-slot ad-slot-' + nome + '" data-ad-slot="' + nome + '">' +
    '<ins class="adsbygoogle" style="display:block" data-ad-client="' + ADSENSE_CLIENT_ID + '" data-ad-format="' + fmt + '" data-full-width-responsive="true"></ins>' +
    '<script>(adsbygoogle = window.adsbygoogle || []).push({});</script>' +
    "</div>"
  );
}

/* Classificação central de página → slot de anúncio, usada só pelo hook
   genérico dentro de paginaChrome() (rotas editoriais/evergreen). Radar,
   Notícia e Home têm posições próprias, mais específicas, e por isso
   ficam de fora daqui (return null) — cada uma resolve seu próprio
   adSlot() no lugar certo, não neste ponto genérico. Minha Escala fica de
   fora de propósito: ferramenta densa em controles, zero anúncio. */
function classificarPaginaParaAds(caminho) {
  if (!caminho) return null;
  if (caminho.startsWith("/radar")) return null;
  if (caminho.startsWith("/noticia")) return null;
  if (caminho === "/minha-escala") return null;
  const ELEGIVEIS = ["/guias", "/funcoes", "/empresas", "/salarios", "/pesquisa-salarial", "/cursos", "/comece-aqui", "/agenda"];
  return ELEGIVEIS.some((p) => caminho === p || caminho.startsWith(p + "/")) ? "content_after_main" : null;
}

