// Expiração/status conservador (Etapa 3.7, 2026-09-24): sem tabela `jobs`
// dedicada (bloqueio de schema já documentado), a única data confiável que
// temos é a verificação manual mais recente (VAGAS_RADAR_VERIFICADO_EM, ou
// v.verificado_em quando uma vaga específica tiver sua própria data). Nunca
// afirmamos "encerrada" por tempo — só reduzimos a confiança e, depois de
// muito tempo sem reverificação, tiramos da listagem ATIVA (nunca da URL).
const VAGA_DIAS_PARA_SUSPEITA = 21;   // acima disso: mostra aviso discreto de verificação antiga
const VAGA_DIAS_PARA_EXPIRAR = 45;    // acima disso: sai da listagem ativa, mas a página permanece no ar
function vagaDataVerificacao(v) {
  return new Date((v && v.verificado_em) || VAGAS_RADAR_VERIFICADO_EM);
}
function vagaDiasDesdeVerificacao(v) {
  return (Date.now() - vagaDataVerificacao(v).getTime()) / 86400000;
}
function vagaPodeEstarDesatualizada(v) {
  const dias = vagaDiasDesdeVerificacao(v);
  return dias > VAGA_DIAS_PARA_SUSPEITA && dias <= VAGA_DIAS_PARA_EXPIRAR;
}
function vagaPodeEstarExpirada(v) {
  return vagaDiasDesdeVerificacao(v) > VAGA_DIAS_PARA_EXPIRAR || v.status === 'CLOSED';
}

function vagasVerificadasTexto() {
  const dt = new Date(VAGAS_RADAR_VERIFICADO_EM);
  return dt.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: 'long', year: 'numeric' }) +
    ' às ' + dt.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
}

function vagasVerificadasHoraCurta() {
  const dt = new Date(VAGAS_RADAR_VERIFICADO_EM);
  return dt.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
}

// NOVO só por tempo limitado (2026-09-19 spec — "não deixar badge NOVA
// durante semanas"): 72h a partir da verificação real, nunca contador
// hardcoded. Aceita uma vaga (Etapa 9, 2026-09-25) pra usar o
// verificado_em individual quando existir, com fallback pro global —
// chamada sem argumento continua funcionando como antes.
function vagaEhNova(v) {
  return (Date.now() - vagaDataVerificacao(v).getTime()) / 3600000 <= 72;
}

function vagaEhBancoTalentos(v) {
  return /banco de talentos|talent pool/i.test((v.titulo || '') + ' ' + (v.job_type || ''));
}
function rotuloTipoVaga(v) {
  return vagaEhBancoTalentos(v) ? 'BANCO DE TALENTOS' : 'VAGA ABERTA';
}
const VAGAS_ABERTAS_ESPECIFICAS = VAGAS_RADAR.filter(v => !vagaEhBancoTalentos(v) && !vagaPodeEstarExpirada(v));

function slugVaga(v) {
  if (v.empresa === 'Foresea') return 'foresea-auxiliar-plataforma-plataformista';
  if (v.empresa === 'Brava Energia') return 'brava-bombeador-offshore';
  if (v.empresa === 'PRIO') return 'prio-engenheiro-projetos-topside-senior';
  if (v.empresa === 'Ocyan') return 'ocyan-caldeireiro-escalador-offshore';
  return ((v.empresa || '') + '-' + (v.titulo || ''))
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}
function vagaPorSlug(slug) { return VAGAS_RADAR.find(v => slugVaga(v) === slug); }

// Home OWNews 2.0 (2026-09-27): ausência de dado não é conteúdo — quando a
// modalidade não é conhecida, o chip simplesmente não aparece (nunca mais
// "Não informado" flutuando ao lado de chips reais). Os 3 casos conhecidos
// continuam exatamente como antes.
function badgeOffshoreOnshore(v) {
  if (v === 'OFFSHORE') return '<span class="vaga-badge vaga-badge-offshore">OFFSHORE</span>';
  if (v === 'ONSHORE') return '<span class="vaga-badge">ONSHORE</span>';
  if (v === 'BASE_MAIS_OFFSHORE') return '<span class="vaga-badge vaga-badge-offshore">BASE + OFFSHORE</span>';
  return '';
}

function cardVaga(v) {
  const slug = slugVaga(v);
  const novo = vagaEhNova(v) ? '<span class="vaga-badge vaga-badge-novo">NOVO</span>' : '';
  return '<div class="area-group" data-vaga-empresa="' + escaparHTML(v.empresa || '') + '" data-vaga-titulo="' + escaparHTML((v.titulo || '').toLowerCase()) + '" data-vaga-modalidade="' + escaparHTML(v.offshore_onshore || 'NAO_INFORMADO') + '" data-vaga-slug="' + escaparHTML(slug) + '">' +
    '<div class="chip-list-flex" style="margin-bottom:8px">' + novo + '<span class="vaga-badge vaga-badge-tipo">' + rotuloTipoVaga(v) + '</span>' + badgeOffshoreOnshore(v.offshore_onshore) + (v.fonte_oficial ? '<span class="campo-pill">✓ Fonte oficial</span>' : '') + (v.local ? '<span class="campo-pill">' + escaparHTML(v.local) + '</span>' : '') +
    (v.escala ? '<span class="campo-pill">Escala: ' + escaparHTML(v.escala) + '</span>' : '') +
    '<button type="button" class="vaga-fav-btn" data-slug="' + escaparHTML(slug) + '" aria-label="Favoritar ' + escaparHTML(v.titulo) + '" aria-pressed="false">&#9734;</button>' +
    '</div>' +
    '<h3>' + escaparHTML(v.titulo) + '</h3>' +
    '<p class="area-desc"><strong>' + escaparHTML(v.empresa) + '</strong> · ' + escaparHTML(v.resumo) + '</p>' +
    '<p class="dado-contexto sem-margem">Fonte: ' + escaparHTML(v.fonte_nome) + ' · Verificada em ' + vagasVerificadasTexto() + '</p>' +
    '<a class="jornada-cta" href="/vagas/' + escaparHTML(slug) + '">Ver detalhes da vaga →</a>' +
    '</div>';
}

// Script mínimo pra ligar botões .vaga-fav-btn renderizados por cardVaga()
// fora de /vagas (Etapa 10: seção "vagas relacionadas" em /funcoes/:slug).
// A própria /vagas tem sua versão integrada ao filtro (scriptFiltroVagas,
// em renderVagasIndex) — nunca as duas juntas na mesma página.
function scriptFavoritarVagasBotoes() {
  return '<script>(function(){' +
    'var FAV_KEY="ownews_vagas_favoritas";' +
    'function getFavoritos(){try{return JSON.parse(localStorage.getItem(FAV_KEY)||"[]");}catch(e){return [];}}' +
    'document.querySelectorAll(".vaga-fav-btn[data-slug]").forEach(function(btn){' +
    'var slug=btn.getAttribute("data-slug");var fav=getFavoritos().indexOf(slug)!==-1;' +
    'btn.classList.toggle("ativo",fav);btn.setAttribute("aria-pressed",fav?"true":"false");btn.innerHTML=fav?"&#9733;":"&#9734;";' +
    'btn.addEventListener("click",function(){var favs=getFavoritos();var i=favs.indexOf(slug);if(i===-1)favs.push(slug);else favs.splice(i,1);try{localStorage.setItem(FAV_KEY,JSON.stringify(favs));}catch(e){}var ativo=favs.indexOf(slug)!==-1;btn.classList.toggle("ativo",ativo);btn.setAttribute("aria-pressed",ativo?"true":"false");btn.innerHTML=ativo?"&#9733;":"&#9734;";});' +
    '});' +
    '})();</script>';
}

// Card compacto/premium pra Home (2026-09-19 — destaque real ao Radar de
// Vagas): mais escaneável que o cardVaga completo (usado em /vagas),
// pensado pra grade de 2-3 colunas / swipe mobile. Nunca mostra dado que
// não existe (escala/local só aparecem quando reais).
function cardVagaHome(v) {
  const novo = vagaEhNova() ? '<span class="vaga-badge vaga-badge-novo">NOVO</span>' : '';
  return '<article class="vaga-card-home">' +
    '<div class="vaga-card-home-badges">' + novo + '<span class="vaga-badge vaga-badge-tipo">' + rotuloTipoVaga(v) + '</span>' + badgeOffshoreOnshore(v.offshore_onshore) + (v.fonte_oficial ? '<span class="campo-pill">✓ Oficial</span>' : '') + '</div>' +
    '<h3>' + escaparHTML(v.titulo) + '</h3>' +
    '<p class="vaga-card-home-empresa">' + escaparHTML(v.empresa) + '</p>' +
    (v.local || v.escala ? '<p class="vaga-card-home-local">' + (v.local ? escaparHTML(v.local) : '') + (v.escala ? (v.local ? ' · ' : '') + 'Escala: ' + escaparHTML(v.escala) : '') + '</p>' : '') +
    '<a class="vaga-card-home-btn" href="/vagas/' + escaparHTML(slugVaga(v)) + '">VER VAGA →</a>' +
    '</article>';
}

