function normalizarBusca(s){
  return (s || '').toString().normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
}

function executarBusca(termo){
  const box = document.getElementById('buscaResultados');
  const q = normalizarBusca(termo).trim();
  if (!box) return;
  if (q.length < 2) { box.hidden = true; box.innerHTML = ''; return; }

  const destinos = INDICE_BUSCA_DESTINOS.filter(d => normalizarBusca(d.titulo).includes(q));
  const noticias = ULTIMAS_NOTICIAS_RADAR.filter(n =>
    normalizarBusca(n.title).includes(q) || normalizarBusca(n.summary).includes(q)
  ).slice(0, 5);

  const resultados = [
    ...destinos.slice(0, 8).map(d => ({ href: d.url, categoria: d.categoria, titulo: d.titulo, sinonimoDe: d.sinonimoDe })),
    ...noticias.map(n => ({ href: '/noticia?id=' + encodeURIComponent(n.id), categoria: 'Notícia', titulo: n.title }))
  ].slice(0, 10);

  if (resultados.length === 0) {
    box.innerHTML = '<div class="search-vazio">Nenhum resultado para "' + termo.replace(/</g,'&lt;') + '".' +
      '<div class="search-sugestoes">' +
      '<a href="/#destaque">Últimas notícias</a>' +
      '<a href="/guias">Guias</a>' +
      '<a href="/empresas">Empresas</a>' +
      '<a href="/funcoes">Funções a bordo</a>' +
      '</div></div>';
  } else {
    box.innerHTML = resultados.map(r =>
      '<a href="' + r.href + '"><span class="search-cat">' + r.categoria + '</span>' + r.titulo.replace(/</g,'&lt;') +
      (r.sinonimoDe ? ' <span class="search-sinonimo">→ ' + r.sinonimoDe.replace(/</g,'&lt;') + '</span>' : '') +
      '</a>'
    ).join('');
  }
  box.hidden = false;
}

const buscaInput = document.getElementById('buscaInput');
if (buscaInput) buscaInput.addEventListener('input', e => executarBusca(e.target.value));

document.getElementById('searchBtn').addEventListener('click', (e) => {
  e.stopPropagation();
  const bar = document.getElementById('searchBar');
  const btn = document.getElementById('searchBtn');
  const open = bar.classList.toggle('open');
  btn.setAttribute('aria-expanded', String(open));
  if (open) { document.getElementById('navLinks').classList.remove('open'); setTimeout(() => buscaInput && buscaInput.focus(), 50); }
});
function fecharBusca(devolverFoco){
  const bar = document.getElementById('searchBar');
  const btn = document.getElementById('searchBtn');
  if (!bar || !bar.classList.contains('open')) return;
  bar.classList.remove('open');
  if (btn) { btn.setAttribute('aria-expanded', 'false'); if (devolverFoco) btn.focus(); }
}
document.addEventListener('click', (e) => {
  const bar = document.getElementById('searchBar');
  const btn = document.getElementById('searchBtn');
  if (bar && !bar.contains(e.target) && e.target !== btn) fecharBusca(false);
});
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') fecharBusca(true);
});

