/* ---------- MODO EMBARCADO (Fase A, 2026-09-18) ----------
   Lido de localStorage ANTES do primeiro render (SEED_ARTICLES) pra já
   nascer sem imagem quando ativo — não é um efeito aplicado depois.
   Zero imagem carrega automaticamente nesse modo: coverStyle() nunca
   emite background-image, só data-attributes; a imagem só é buscada de
   verdade se o usuário clicar em "Carregar imagem" (carregarImagemCover). */
let MODO_EMBARCADO = false;
try { MODO_EMBARCADO = localStorage.getItem('ownews_embarcado') === '1'; } catch (e) {}

function aplicarClasseEmbarcado(){
  try { document.documentElement.classList.toggle('embarcado', MODO_EMBARCADO); } catch (e) {}
  const btn = document.getElementById('embarcadoBtn');
  if (btn) btn.setAttribute('aria-pressed', MODO_EMBARCADO ? 'true' : 'false');
  const label = document.getElementById('embarcadoBtnLabel');
  const sub = document.getElementById('embarcadoBtnSub');
  if (label) label.textContent = MODO_EMBARCADO ? 'Modo Embarcado Ativo' : 'Modo Embarcado';
  if (sub) sub.textContent = MODO_EMBARCADO ? 'Voltar ao modo completo' : 'Versão leve para internet a bordo';
  if (btn) btn.title = MODO_EMBARCADO ? 'Voltar ao modo completo' : 'Versão leve para internet a bordo';
}
aplicarClasseEmbarcado();

function carregarImagemCover(ev){
  ev.stopPropagation();
  const div = ev.currentTarget.closest('.cover, .thumb');
  if (!div) return;
  const url = div.dataset.coverUrl;
  const variant = div.dataset.coverVariant || '';
  if (url) div.setAttribute('style', "background-image:url('" + url + "');" + variant);
  ev.currentTarget.remove();
}

