// Áreas de Funções a Bordo relacionadas a cada categoria de empresa —
// mesma lógica de antes, só remapeada pras novas chaves de categoria.
const CATEGORIA_AREAS_RELACIONADAS = {
  perfuracao: ["drilling"], producao_fpso: ["deck", "engine"], subsea_rov: ["subsea"],
  servicos_poco: ["engine"], apoio_maritimo: ["marine"], operadoras: [],
  engenharia_manutencao: ["engine", "seguranca"], hotelaria: ["catering"], logistica_servicos: ["logistica"]
};

const AVISO_ANTIFRAUDE_EMPRESAS =
  'O OWNews prioriza canais oficiais de recrutamento. Desconfie de cobranças, promessas de contratação ou pedidos de pagamento para participar de processos seletivos.';

function cardEmpresa(e) {
  const categoriasNomes = e.categorias.map((c) => CATEGORIAS_EMPRESAS[c] || c).join(' · ');
  const cta = CTA_POR_TIPO_CANAL[e.tipoCanal] || 'Portal de carreiras ↗';
  return (
    '<article class="empresa-card" id="' + escaparHTML(e.slug) + '" data-categorias="' + e.categorias.join(' ') + '" data-nome="' + escaparHTML(e.nome.toLowerCase()) + '">' +
    '<div class="empresa-head"><h3><a href="/empresas/' + escaparHTML(e.slug) + '">' + escaparHTML(e.nome) + '</a></h3></div>' +
    '<p class="empresa-segmento-tag">' + escaparHTML(categoriasNomes) + '</p>' +
    '<a class="empresa-cta" href="' + escaparHTML(e.careersUrl) + '" target="_blank" rel="noopener noreferrer">' + cta + '</a>' +
    '</article>'
  );
}

function empresaPorSlug(slug) {
  return EMPRESAS_CARREIRAS.find((e) => e.slug === slug) || null;
}

// Etapa 11 (Diretório Offshore 2.0, 2026-09-25): vagas do Radar realmente
// associadas a uma empresa do diretório — comparação direta de nome (mesmo
// campo `empresa` já usado em VAGAS_RADAR/cardVaga, sem substring solta).
function vagasDaEmpresaDiretorio(e) {
  return VAGAS_RADAR.filter((v) => !vagaPodeEstarExpirada(v) && v.empresa === e.nome);
}

/* ---------- /empresas/:slug ----------
   Página individual (Etapa 11): junta o que o OWNews já sabe sobre a
   empresa — categoria(s), canal oficial, vagas reais do Radar e notícias
   reais que mencionam o nome dela (busca direta na Supabase, mesmo
   padrão/chave pública já usado em toda a Home e em /noticia, nenhum
   endpoint novo). Sem unidades/contratos/relações inventadas — só o que
   existe hoje: vagas e notícias. */
async function renderEmpresaDetalhe(slug) {
  const e = empresaPorSlug(slug);
  if (!e) return null;
  const categoriasNomes = e.categorias.map((c) => CATEGORIAS_EMPRESAS[c] || c).join(' · ');
  const cta = CTA_POR_TIPO_CANAL[e.tipoCanal] || 'Portal de carreiras ↗';
  const vagasEmpresa = vagasDaEmpresaDiretorio(e);

  let noticiasEmpresa = [];
  try {
    const supabaseUrl = 'https://awyowuhwkqfyhwgdpepp.supabase.co';
    const supabaseKey = 'sb_publishable_9cRatirjls8SQIoHdTUkLQ_8jt6psGt';
    const termo = encodeURIComponent('*' + e.nome + '*');
    const apiUrl = supabaseUrl + '/rest/v1/articles?status=eq.published&title=ilike.' + termo +
      '&select=id,title,published_at&order=published_at.desc&limit=4';
    const resp = await fetch(apiUrl, { headers: { apikey: supabaseKey, Authorization: 'Bearer ' + supabaseKey } });
    if (resp.ok) noticiasEmpresa = await resp.json();
  } catch (err) { /* indisponibilidade da Supabase não derruba a página — só some a seção */ }

  const conteudo =
    breadcrumb([{ nome: 'Home', href: '/' }, { nome: 'Empresas Offshore', href: '/empresas' }, { nome: e.nome }]) +
    '<div class="hub-hero">' +
    '<span class="eyebrow">' + escaparHTML(categoriasNomes) + '</span>' +
    '<h1>' + escaparHTML(e.nome) + '</h1>' +
    '<p class="hub-lead">Referência editorial do OWNews — não é parceria comercial. Canal de recrutamento verificado diretamente na empresa em ' + escaparHTML(e.dataVerificacao) + '.</p>' +
    '<a class="hub-cta-secundario" href="' + escaparHTML(e.careersUrl) + '" target="_blank" rel="noopener noreferrer">' + cta + '</a>' +
    '</div>' +
    (vagasEmpresa.length
      ? '<section class="area-group"><h2>VAGAS ABERTAS DESTA EMPRESA NO OWNEWS</h2><div class="campo-grid">' + vagasEmpresa.map(cardVaga).join('') + '</div></section>' + scriptFavoritarVagasBotoes()
      : '') +
    (noticiasEmpresa.length
      ? '<section class="area-group"><h2>NOTÍCIAS RECENTES</h2><div class="role-list">' +
        noticiasEmpresa.map((n) => '<a class="role-row" href="/noticia?id=' + escaparHTML(n.id) + '"><span class="role-nome">' + escaparHTML(decodificarEntidadesHTMLServidor(n.title)) + '</span><span class="go">→</span></a>').join('') +
        '</div></section>'
      : '') +
    '<div class="hub-continue">' +
    '<span class="hub-continue-label">Continue no OWNews</span>' +
    '<a href="/empresas">← Todas as empresas</a>' +
    '<a href="/vagas">Vagas Verificadas →</a>' +
    '<a href="/carreiras/cadastre-seu-curriculo">Cadastre seu currículo →</a>' +
    '</div>';

  return paginaChrome(
    e.nome + ' — Empresas Offshore',
    'Categoria, canal oficial de recrutamento, vagas e notícias recentes sobre a ' + e.nome + ' no setor offshore brasileiro.',
    conteudo,
    '/empresas/' + e.slug
  );
}

// Regra 2.17 (expansão 2026-09-17): categoria com ZERO empresas aprovadas
// não aparece no filtro — nem com rótulo "em breve". Só categorias com
// pelo menos 1 empresa publicada existem para o usuário.
function filtrosCategoriaHtml(idPrefixo) {
  const categoriasPresentes = Array.from(new Set(EMPRESAS_CARREIRAS.flatMap((e) => e.categorias)));
  const todasCategorias = Object.keys(CATEGORIAS_EMPRESAS).filter((c) => categoriasPresentes.includes(c));
  const btns = ['<button type="button" class="filtro-btn ativo" data-categoria="todas">Todas</button>']
    .concat(todasCategorias.map((c) =>
      '<button type="button" class="filtro-btn" data-categoria="' + c + '">' + escaparHTML(CATEGORIAS_EMPRESAS[c]) + '</button>'
    ));
  return '<div class="filtro-segmento-row" id="' + idPrefixo + 'Filtros">' + btns.join('') + '</div>';
}

function scriptBuscaFiltroEmpresas(gridId, filtrosId) {
  return (
    '<script>' +
    '(function(){' +
    'var grid=document.getElementById("' + gridId + '");' +
    'var filtros=document.getElementById("' + filtrosId + '");' +
    'if(!grid||!filtros)return;' +
    'var botoes=Array.prototype.slice.call(filtros.querySelectorAll(".filtro-btn"));' +
    'var cards=Array.prototype.slice.call(grid.querySelectorAll(".empresa-card"));' +
    'var busca=document.getElementById("' + gridId + 'Busca");' +
    'var vazio=document.getElementById("' + gridId + 'Vazio");' +
    'var categoriaAtiva="todas";' +
    'function normalizar(s){return (s||"").toString().normalize("NFD").replace(/[\\u0300-\\u036f]/g,"").toLowerCase();}' +
    'function aplicar(){' +
    'var termo=normalizar(busca?busca.value:"");' +
    'var visiveis=0;' +
    'cards.forEach(function(c){' +
    'var cats=(c.getAttribute("data-categorias")||"").split(" ");' +
    'var passaCategoria=categoriaAtiva==="todas"||cats.indexOf(categoriaAtiva)!==-1;' +
    'var passaBusca=!termo||normalizar(c.getAttribute("data-nome")).indexOf(termo)!==-1||normalizar(c.textContent).indexOf(termo)!==-1;' +
    'var mostra=passaCategoria&&passaBusca;' +
    'c.hidden=!mostra;' +
    'if(mostra)visiveis++;' +
    '});' +
    'if(vazio)vazio.hidden=visiveis>0;' +
    '}' +
    'botoes.forEach(function(b){b.addEventListener("click",function(){' +
    'categoriaAtiva=b.getAttribute("data-categoria");' +
    'botoes.forEach(function(x){x.classList.toggle("ativo",x===b);});' +
    'aplicar();' +
    '});});' +
    'if(busca)busca.addEventListener("input",aplicar);' +
    '})();' +
    '</script>'
  );
}

