function explicaPorSlug(slug) { return EXPLICA_ARTIGOS.find((e) => e.slug === slug) || null; }

function cardExplica(e) {
  return '<a class="role-row" href="/explica/' + e.slug + '">' +
    '<span class="role-nome">' + escaparHTML(e.titulo) + '</span>' +
    '<span class="go">→</span>' +
    '</a>';
}

function renderExplicaIndex() {
  const porCategoria = {};
  EXPLICA_ARTIGOS.forEach((e) => { (porCategoria[e.categoria] = porCategoria[e.categoria] || []).push(e); });
  const grupos = Object.keys(porCategoria).map((cat) =>
    '<div class="area-group"><h3>' + escaparHTML(cat) + '</h3><div class="role-list">' +
    porCategoria[cat].map(cardExplica).join('') + '</div></div>'
  ).join('');

  const conteudo =
    breadcrumb([{ nome: "Home", href: "/" }, { nome: "OWNews Explica" }]) +
    '<div class="hub-hero">' +
    '<span class="eyebrow">Referência OWNews</span>' +
    '<h1>OWNews Explica</h1>' +
    '<p class="hub-lead">Conceitos e processos do offshore explicados de forma clara e direta — o que é, como funciona e por que importa. ' + EXPLICA_ARTIGOS.length + ' verbetes até agora.</p>' +
    '</div>' +
    grupos +
    '<div class="hub-continue">' +
    '<span class="hub-continue-label">Continue no OWNews</span>' +
    '<a href="/glossario">Glossário Offshore →</a>' +
    '<a href="/funcoes">Funções a Bordo →</a>' +
    '</div>';

  return paginaChrome(
    "OWNews Explica",
    "Conceitos e processos do offshore explicados de forma clara: o que é, como funciona e por que importa — FPSO, BOP, ROV, completação, descomissionamento e mais.",
    conteudo,
    "/explica"
  );
}

function renderExplicaDetalhe(slug) {
  const e = explicaPorSlug(slug);
  if (!e) return null;

  const termosHtml = e.termosRelacionados.length
    ? '<div class="chip-list-flex">' + e.termosRelacionados.map((sigla) => {
        const t = GLOSSARIO_TERMOS.find((g) => g.sigla === sigla);
        return t ? '<span class="campo-pill" title="' + escaparHTML(t.def) + '">' + escaparHTML(sigla) + '</span>' : '';
      }).join('') + '</div>'
    : '';

  const outrosExplica = EXPLICA_ARTIGOS.filter((o) => o.slug !== e.slug && o.categoria === e.categoria).slice(0, 3);

  const conteudo =
    breadcrumb([{ nome: "Home", href: "/" }, { nome: "OWNews Explica", href: "/explica" }, { nome: e.titulo }]) +
    '<div class="hub-hero">' +
    '<span class="eyebrow">OWNews Explica · ' + escaparHTML(e.categoria) + '</span>' +
    '<h1>' + escaparHTML(e.titulo) + '</h1>' +
    '<p class="hub-lead">' + escaparHTML(e.respostaCurta) + '</p>' +
    '</div>' +
    '<section class="area-group"><h2>EXPLICAÇÃO</h2><p class="area-desc">' + escaparHTML(e.explicacao) + '</p></section>' +
    '<section class="area-group"><h2>COMO FUNCIONA</h2><p class="area-desc">' + escaparHTML(e.comoFunciona) + '</p></section>' +
    '<section class="area-group"><h2>POR QUE IMPORTA NO OFFSHORE</h2><p class="area-desc">' + escaparHTML(e.porQueImporta) + '</p></section>' +
    (termosHtml ? '<section class="area-group"><h2>TERMOS RELACIONADOS</h2>' + termosHtml + '</section>' : '') +
    (outrosExplica.length ? '<section class="area-group"><h2>VEJA TAMBÉM</h2><div class="role-list">' + outrosExplica.map(cardExplica).join('') + '</div></section>' : '') +
    '<div class="hub-continue">' +
    '<span class="hub-continue-label">Continue no OWNews</span>' +
    '<a href="/explica">← OWNews Explica</a>' +
    (e.relacionado ? '<a href="' + escaparHTML(e.relacionado.href) + '">' + escaparHTML(e.relacionado.label) + '</a>' : '') +
    '<a href="/glossario">Glossário Offshore →</a>' +
    '</div>';

  return paginaChrome(
    e.titulo + " | OWNews Explica",
    e.respostaCurta,
    conteudo,
    "/explica/" + e.slug,
    { eventoAbertura: 'explica_aberto' }
  );
}

/* =========================================================================
   AVIAÇÃO OFFSHORE (Missão Complementar, 2026-09-26) — hub de referência
   sobre a aviação que conecta o trabalhador ao mar. NUNCA duplica
   Aeroportos/REDEMET/OffVoos (reaproveita DATASET_AEROPORTOS_OFFSHORE e
   o próprio /aeroportos) nem OWNews Explica (reaproveita os verbetes já
   existentes de transporte aéreo/troca de turma). Só 4 aeronaves
   catalogadas nesta fase, cada uma com specs vindas DIRETO do fabricante
   (Lockheed Martin/Leonardo/Airbus) — nenhum dado de memória, nenhuma
   operação no Brasil afirmada sem fonte. Capacidade sempre registrada
   como variável por configuração (nunca um número universal). ========= */
// Banco visual (adendo "Política Visual de Ativos Reais", 2026-09-26):
// adaptado à MESMA arquitetura já usada em UNIDADES_RADAR (foto_url/
// foto_credito/foto_fonte_url/foto_licenca por entidade — nunca uma
// tabela paralela). Fotos hospedadas no Wikimedia Commons — cada uma
// verificada individualmente nesta missão (identificação do modelo
// conferida visualmente, licença e crédito confirmados na própria
// página do arquivo). Miniaturas via o próprio redimensionador oficial
// do Commons (larguras padrão permitidas: 20/40/60/120/250/330/500/960/
// 1280/1920/3840px — qualquer outra largura é rejeitada com HTTP 400,
// confirmado em teste real) — zero processamento/hospedagem própria
// necessária, zero peso extra no bundle do Worker.
function commonsThumbUrl(hashPath, arquivo, largura) {
  const enc = encodeURIComponent(arquivo);
  return "https://upload.wikimedia.org/wikipedia/commons/thumb/" + hashPath + "/" + enc + "/" + largura + "px-" + enc;
}

