function unidadeRadarPorSlug(slug) {
  return UNIDADES_RADAR.find((u) => u.slug === slug) || null;
}

// Etapa 15.1/15.2 (Radar de Unidades, 2026-09-25): elo UNIDADE → EMPRESA
// usando a mesma fundação da Etapa 12 (borda de palavra real contra o
// Diretório inteiro) — aplicado a operador/owner/contratante, os únicos
// campos de texto livre que citam empresas de verdade. Pode retornar
// mais de uma empresa quando o texto realmente cita várias (ex.: parceria
// de consórcio) — nunca inventa uma relação única forçada.
function empresasRelacionadasUnidade(u) {
  const texto = [u.operador, u.owner, u.contratante].filter(Boolean).join(' ');
  if (!texto) return [];
  return EMPRESAS_CARREIRAS.filter((e) => {
    if (!e.nome || e.nome.length < 4) return false;
    const escapado = e.nome.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return new RegExp('\\b' + escapado + '\\b', 'i').test(texto);
  });
}

// UNIDADE → VAGA, só através da empresa relacionada real (nunca direto
// por texto livre) — reaproveita vagasDaEmpresaDiretorio já usada em
// /empresas/:slug, sem duplicar lógica de match.
function vagasRelacionadasUnidade(u) {
  const empresas = empresasRelacionadasUnidade(u);
  const vistas = new Set();
  const resultado = [];
  empresas.forEach((e) => {
    vagasDaEmpresaDiretorio(e).forEach((v) => {
      const chave = slugVaga(v);
      if (!vistas.has(chave)) { vistas.add(chave); resultado.push(v); }
    });
  });
  return resultado;
}

/* Só renderiza o campo se houver dado real — regra absoluta da Fase 2:
   nunca mostrar "Não disponível"/"Indisponível"/traço vazio. Ausência de
   dado = ausência de elemento na interface. */
function campoOuNada(label, valor) {
  if (valor === null || valor === undefined || valor === "") return "";
  return campoEstrutura(label, '<span class="dado-valor">' + escaparHTML(String(valor)) + "</span>");
}

