/* =========================================================================
   MAIS LIDAS (Etapa 7, 2026-09-24) — a rota interna "/top" da PageViews já
   existia, pronta, desde a rodada que criou a Durable Object (comentário
   original: "pronta pra quando 'Mais Lidas' for exibido"). Auditoria desta
   etapa: dados reais sendo gravados desde 2026-09-17 via
   scriptRegistrarPageview em toda página de notícia — nenhum dado
   inventado, nenhuma integração nova, só a rota pública que faltava.

   Threshold conservador: só mostra o bloco quando há pelo menos
   MAIS_LIDAS_MINIMO_ITENS matérias com pelo menos MAIS_LIDAS_VIEWS_MINIMO
   views reais nos últimos 7 dias — abaixo disso, a seção fica ausente
   (nunca aparece com "1 view" fingindo ranking relevante; "mostrar menos"
   já é o padrão usado em todo o resto da Home). ========================= */
const MAIS_LIDAS_VIEWS_MINIMO = 3;
const MAIS_LIDAS_MINIMO_ITENS = 3;

async function responderMaisLidas(request, env) {
  const headers = { "Content-Type": "application/json; charset=UTF-8", "Cache-Control": "public, max-age=300" };

  if (!env || !env.PAGEVIEWS) {
    return new Response(JSON.stringify({ itens: [] }), { status: 503, headers });
  }

  try {
    const idDO = env.PAGEVIEWS.idFromName("global");
    const stub = env.PAGEVIEWS.get(idDO);
    const respostaDO = await stub.fetch("https://pageviews.interno/top?horas=168&limite=10");
    const dadosDO = await respostaDO.json();
    const rankeados = (dadosDO.itens || []).filter((it) => it.views >= MAIS_LIDAS_VIEWS_MINIMO);
    if (rankeados.length < MAIS_LIDAS_MINIMO_ITENS) {
      return new Response(JSON.stringify({ itens: [] }), { status: 200, headers });
    }

    const ids = rankeados.slice(0, 5).map((it) => it.article_id);
    const supabaseUrl = "https://awyowuhwkqfyhwgdpepp.supabase.co";
    const supabaseKey = "sb_publishable_9cRatirjls8SQIoHdTUkLQ_8jt6psGt";
    const idsParam = ids.map((id) => encodeURIComponent(id)).join(",");
    const respArtigos = await fetch(
      supabaseUrl + "/rest/v1/articles?select=id,title,image_url,image_credit,published_at&status=eq.published&id=in.(" + idsParam + ")",
      { headers: { apikey: supabaseKey } }
    );
    const artigos = respArtigos.ok ? await respArtigos.json() : [];
    const porId = new Map(artigos.map((a) => [a.id, a]));
    // Reordena pela contagem real de views (a query "in" não preserva ordem);
    // artigo apagado/despublicado depois de contabilizado simplesmente some
    // da lista, nunca vira erro.
    const itens = ids.map((id) => porId.get(id)).filter(Boolean)
      .map((a) => (a.title ? { ...a, title: decodificarEntidadesHTMLServidor(a.title) } : a));
    return new Response(JSON.stringify({ itens }), { status: 200, headers });
  } catch {
    return new Response(JSON.stringify({ itens: [] }), { status: 503, headers });
  }
}

/* Command Center — padronização do período "Hoje" (2026-09-27): 00:00 no
   fuso America/Sao_Paulo até agora, pra TODAS as métricas do filtro.
   Armazenamento continua 100% UTC; só a agregação converte. Usa
   Intl.DateTimeFormat com timeZone real (ICU do workerd) — nunca offset
   fixo -03:00 hardcoded (pedido explícito da missão; se o Brasil voltar
   a ter horário de verão, isto continua correto sozinho). */
function offsetDoFusoMs(fuso, ts) {
  const partes = new Intl.DateTimeFormat("en-US", {
    timeZone: fuso, hour12: false,
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit"
  }).formatToParts(new Date(ts));
  const g = Object.fromEntries(partes.filter((p) => p.type !== "literal").map((p) => [p.type, p.value]));
  const lidoComoUtc = Date.UTC(+g.year, +g.month - 1, +g.day, +g.hour % 24, +g.minute, +g.second);
  return lidoComoUtc - ts;
}
function inicioDoDiaNoFuso(agoraTs, fuso) {
  const dataLocal = new Intl.DateTimeFormat("en-CA", { timeZone: fuso }).format(new Date(agoraTs)); // "YYYY-MM-DD"
  const meiaNoiteLidaComoUtc = Date.parse(dataLocal + "T00:00:00Z");
  let ts = meiaNoiteLidaComoUtc - offsetDoFusoMs(fuso, meiaNoiteLidaComoUtc);
  // refina 1x pra fronteira de mudança de offset (DST) cair certo
  const off2 = offsetDoFusoMs(fuso, ts);
  if (meiaNoiteLidaComoUtc - off2 !== ts) ts = meiaNoiteLidaComoUtc - off2;
  return ts;
}

export class PageViews {
  constructor(state) {
    this.state = state;
    this.sql = state.storage.sql;
    this.taxaPorSessao = new Map();
    this.pronto = this.inicializar();
  }

  async inicializar() {
    this.sql.exec("CREATE TABLE IF NOT EXISTS views (article_id TEXT NOT NULL, session_id TEXT NOT NULL, ts INTEGER NOT NULL)");
    this.sql.exec("CREATE INDEX IF NOT EXISTS idx_views_ts ON views(ts)");
    this.sql.exec("CREATE INDEX IF NOT EXISTS idx_views_article_ts ON views(article_id, ts)");
    // Contador real de visitas do site (rodapé, 2026-09-17). "visit_days"
    // só existe para dedupe (1 visita contada por sessão por dia) e pode
    // ser podada com segurança (dedupe só importa dentro do próprio dia);
    // "totals" é o acumulado histórico e NUNCA é apagado/decrescido —
    // tabela separada de propósito, pra nenhuma rotina de limpeza chegar
    // perto dela.
    this.sql.exec("CREATE TABLE IF NOT EXISTS visit_days (session_id TEXT NOT NULL, day TEXT NOT NULL, PRIMARY KEY (session_id, day))");
    this.sql.exec("CREATE TABLE IF NOT EXISTS totals (key TEXT PRIMARY KEY, value INTEGER NOT NULL, first_recorded_at INTEGER NOT NULL)");
    // Command Center (2026-09-26): camada de analytics própria, MESMO
    // Durable Object/arquitetura já existente (nunca um serviço externo
    // novo) — pageviews_raw guarda 1 linha por carregamento de página
    // real (não deduplicado, ao contrário de visit_days) com classificação
    // server-side de dispositivo/origem (nunca User-Agent/referrer cru:
    // classificado em poucas categorias na escrita, sem PII). events
    // guarda os eventos próprios de uso de ferramenta (minha_escala_aberta,
    // vaga_compartilhada etc.) — só nome/caminho/sessão/tempo.
    this.sql.exec("CREATE TABLE IF NOT EXISTS pageviews_raw (path TEXT NOT NULL, session_id TEXT NOT NULL, ref_tipo TEXT, dispositivo TEXT, ts INTEGER NOT NULL)");
    this.sql.exec("CREATE INDEX IF NOT EXISTS idx_pvraw_ts ON pageviews_raw(ts)");
    this.sql.exec("CREATE INDEX IF NOT EXISTS idx_pvraw_path_ts ON pageviews_raw(path, ts)");
    this.sql.exec("CREATE TABLE IF NOT EXISTS events (name TEXT NOT NULL, path TEXT, session_id TEXT NOT NULL, ts INTEGER NOT NULL)");
    this.sql.exec("CREATE INDEX IF NOT EXISTS idx_events_ts ON events(ts)");
    this.sql.exec("CREATE INDEX IF NOT EXISTS idx_events_name_ts ON events(name, ts)");
    const alarmeExiste = await this.state.storage.getAlarm();
    if (!alarmeExiste) await this.state.storage.setAlarm(Date.now() + 3600000);
  }

  /* Limite generoso — não é anti-abuso fino (não há IP nem captcha aqui),
     só um teto contra um cliente com bug/malicioso martelando o endpoint. */
  limitarTaxa(sessionId) {
    const agora = Date.now();
    const janela = this.taxaPorSessao.get(sessionId);
    if (!janela || agora - janela.inicio > 60000) {
      this.taxaPorSessao.set(sessionId, { inicio: agora, contagem: 1 });
      if (this.taxaPorSessao.size > 5000) this.taxaPorSessao.clear();
      return true;
    }
    janela.contagem++;
    return janela.contagem <= 20;
  }

  async fetch(request) {
    await this.pronto;
    const url = new URL(request.url);

    if (request.method === "POST" && url.pathname === "/registrar") {
      let corpo = {};
      try { corpo = await request.json(); } catch {}
      const articleId = corpo && corpo.articleId;
      const sessionId = corpo && corpo.sessionId;
      if (!articleId || !sessionId) {
        return new Response(JSON.stringify({ ok: false }), { status: 400 });
      }
      if (!this.limitarTaxa(sessionId)) {
        return new Response(JSON.stringify({ ok: false, motivo: "rate_limit" }), { status: 429 });
      }

      const agora = Date.now();
      const cursorDedupe = this.sql.exec(
        "SELECT ts FROM views WHERE article_id = ? AND session_id = ? AND ts > ? LIMIT 1",
        articleId, sessionId, agora - JANELA_DEDUPE_PAGEVIEW_MS
      );
      const jaViu = [...cursorDedupe].length > 0;
      if (!jaViu) {
        this.sql.exec("INSERT INTO views (article_id, session_id, ts) VALUES (?, ?, ?)", articleId, sessionId, agora);
      }
      return new Response(JSON.stringify({ ok: true, counted: !jaViu }), {
        headers: { "Content-Type": "application/json" }
      });
    }

    if (request.method === "POST" && url.pathname === "/visita") {
      let corpo = {};
      try { corpo = await request.json(); } catch {}
      const sessionId = corpo && corpo.sessionId;
      if (!sessionId) {
        return new Response(JSON.stringify({ ok: false }), { status: 400 });
      }
      if (!this.limitarTaxa("visita:" + sessionId)) {
        return new Response(JSON.stringify({ ok: false, motivo: "rate_limit" }), { status: 429 });
      }

      const agora = Date.now();
      const dia = new Date(agora).toISOString().slice(0, 10); // dedupe por dia (UTC), granularidade suficiente
      let contada = false;
      try {
        this.sql.exec("INSERT INTO visit_days (session_id, day) VALUES (?, ?)", sessionId, dia);
        contada = true;
      } catch {
        contada = false; // já existia (PRIMARY KEY) — mesma sessão, mesmo dia
      }

      if (contada) {
        const existente = [...this.sql.exec("SELECT value FROM totals WHERE key = 'site_visits'")];
        if (existente.length) {
          this.sql.exec("UPDATE totals SET value = value + 1 WHERE key = 'site_visits'");
        } else {
          this.sql.exec(
            "INSERT INTO totals (key, value, first_recorded_at) VALUES ('site_visits', 1, ?)",
            agora
          );
        }
      }

      // Command Center: registro NÃO deduplicado (1 linha por carregamento
      // real de página, não por sessão/dia) — é o que alimenta
      // "Visualizações" e "Páginas mais acessadas", distinto de
      // "Visitantes" (que usa visit_days, deduplicado). path/refTipo/
      // dispositivo já vêm classificados pelo Worker antes de chegar aqui.
      const path = typeof corpo.path === "string" ? corpo.path.slice(0, 200) : "/";
      const refTipo = typeof corpo.refTipo === "string" ? corpo.refTipo.slice(0, 40) : null;
      const dispositivo = typeof corpo.dispositivo === "string" ? corpo.dispositivo.slice(0, 20) : null;
      this.sql.exec(
        "INSERT INTO pageviews_raw (path, session_id, ref_tipo, dispositivo, ts) VALUES (?, ?, ?, ?, ?)",
        path, sessionId, refTipo, dispositivo, agora
      );

      return new Response(JSON.stringify({ ok: true, counted: contada }), {
        headers: { "Content-Type": "application/json" }
      });
    }

    if (request.method === "GET" && url.pathname === "/total") {
      const linha = [...this.sql.exec("SELECT value, first_recorded_at FROM totals WHERE key = 'site_visits'")][0];
      if (!linha) {
        return new Response(JSON.stringify({ total: 0, desde: null }), {
          headers: { "Content-Type": "application/json" }
        });
      }
      const desde = new Date(linha.first_recorded_at);
      const desdeFormatado =
        String(desde.getUTCDate()).padStart(2, "0") + "/" +
        String(desde.getUTCMonth() + 1).padStart(2, "0") + "/" +
        desde.getUTCFullYear();
      return new Response(JSON.stringify({ total: linha.value, desde: desdeFormatado }), {
        headers: { "Content-Type": "application/json" }
      });
    }

    // Command Center: evento próprio de uso de ferramenta (nunca PII —
    // só nome do evento, caminho e sessão efêmera já usada em toda a
    // camada de analytics existente).
    if (request.method === "POST" && url.pathname === "/evento") {
      let corpo = {};
      try { corpo = await request.json(); } catch {}
      const name = typeof corpo.name === "string" ? corpo.name.slice(0, 60) : "";
      const sessionId = typeof corpo.sessionId === "string" ? corpo.sessionId : "";
      const path = typeof corpo.path === "string" ? corpo.path.slice(0, 200) : null;
      if (!name || !sessionId || !/^[a-z0-9_]+$/.test(name)) {
        return new Response(JSON.stringify({ ok: false }), { status: 400 });
      }
      if (!this.limitarTaxa("evento:" + sessionId)) {
        return new Response(JSON.stringify({ ok: false, motivo: "rate_limit" }), { status: 429 });
      }
      this.sql.exec("INSERT INTO events (name, path, session_id, ts) VALUES (?, ?, ?, ?)", name, path, sessionId, Date.now());
      return new Response(JSON.stringify({ ok: true }), { headers: { "Content-Type": "application/json" } });
    }

    // Command Center: resumo agregado por período — única rota que o
    // painel privado consulta (nunca dado individual/sessão/IP exposto).
    if (request.method === "GET" && url.pathname === "/resumo") {
      const periodo = url.searchParams.get("periodo") || "hoje";
      const diasPeriodo = periodo === "hoje" ? 1 : periodo === "7d" ? 7 : periodo === "30d" ? 30 : null;
      const agora = Date.now();
      const hojeStr = new Date(agora).toISOString().slice(0, 10);
      // Padronização "Hoje" (2026-09-27): 00:00 America/Sao_Paulo → agora,
      // MESMA janela pra todas as métricas (antes: visitantes por dia UTC,
      // visualizações por 24h móveis — janelas incoerentes no mesmo filtro).
      const ehHoje = periodo === "hoje";
      // Padronização estendida a 7d/30d (2026-09-27, pendência declarada
      // na correção anterior): TODO período fechado passa a começar às
      // 00:00 America/Sao_Paulo do primeiro dia da janela — "7 dias" =
      // hoje + os 6 dias anteriores, não 168h móveis. Antes, só "Hoje"
      // usava calendário BRT e 7d/30d usavam janela móvel, o que voltava
      // a misturar duas definições dentro do mesmo painel.
      // `inicioDoDiaNoFuso` é aplicado sobre o instante deslocado (e não
      // uma subtração fixa de 86400000) pra continuar correto se o Brasil
      // voltar a ter horário de verão.
      const desdeTs = diasPeriodo
        ? inicioDoDiaNoFuso(agora - (diasPeriodo - 1) * 86400000, "America/Sao_Paulo")
        : 0;
      const desdeStr = diasPeriodo ? new Date(desdeTs).toISOString().slice(0, 10) : "2020-01-01";

      // "Hoje": visitantes únicos da MESMA fonte/janela das visualizações
      // (pageviews_raw tem session_id + timestamp exato — permite alinhar
      // ao minuto, coisa que visit_days, com granularidade de dia UTC,
      // não permite). Períodos maiores continuam em visit_days (deduplicado
      // por dia, com histórico mais antigo que pageviews_raw).
      const visitantes = ehHoje
        ? ([...this.sql.exec(
            "SELECT COUNT(DISTINCT session_id) as c FROM pageviews_raw WHERE ts >= ?", desdeTs
          )][0]?.c || 0)
        : ([...this.sql.exec(
            "SELECT COUNT(DISTINCT session_id) as c FROM visit_days WHERE day >= ? AND day <= ?", desdeStr, hojeStr
          )][0]?.c || 0);
      const visualizacoes = [...this.sql.exec(
        "SELECT COUNT(*) as c FROM pageviews_raw WHERE ts >= ?", desdeTs
      )][0]?.c || 0;
      const eventos = [...this.sql.exec(
        "SELECT name, COUNT(*) as c FROM events WHERE ts >= ? GROUP BY name ORDER BY c DESC", desdeTs
      )];
      const topPaths = [...this.sql.exec(
        "SELECT path, COUNT(*) as c FROM pageviews_raw WHERE ts >= ? GROUP BY path ORDER BY c DESC LIMIT 15", desdeTs
      )];
      const origens = [...this.sql.exec(
        "SELECT ref_tipo, COUNT(*) as c FROM pageviews_raw WHERE ts >= ? AND ref_tipo IS NOT NULL GROUP BY ref_tipo ORDER BY c DESC", desdeTs
      )];
      const dispositivos = [...this.sql.exec(
        "SELECT dispositivo, COUNT(*) as c FROM pageviews_raw WHERE ts >= ? AND dispositivo IS NOT NULL GROUP BY dispositivo ORDER BY c DESC", desdeTs
      )];
      // Recorrentes: sessões do período que já tinham visita ANTES do
      // início do período (dentro da retenção de 65 dias). Novos: o
      // resto. Aproximação documentada — sessão que some por mais tempo
      // que a retenção volta a contar como "nova". No "Hoje", a sessão
      // ativa vem de pageviews_raw (mesma janela BRT das demais métricas)
      // e o histórico continua vindo de visit_days (dia UTC — a fronteira
      // de ±3h é limitação de granularidade documentada, não regressão).
      const recorrentes = ehHoje
        ? ([...this.sql.exec(
            "SELECT COUNT(DISTINCT p.session_id) as c FROM pageviews_raw p WHERE p.ts >= ? AND EXISTS (SELECT 1 FROM visit_days vd WHERE vd.session_id = p.session_id AND vd.day < ?)",
            desdeTs, new Date(desdeTs).toISOString().slice(0, 10)
          )][0]?.c || 0)
        : diasPeriodo ? ([...this.sql.exec(
            "SELECT COUNT(DISTINCT vd.session_id) as c FROM visit_days vd WHERE vd.day >= ? AND vd.day <= ? AND EXISTS (SELECT 1 FROM visit_days vd2 WHERE vd2.session_id = vd.session_id AND vd2.day < ?)",
            desdeStr, hojeStr, desdeStr
          )][0]?.c || 0) : null;

      // Desde quando existe dado de visualização/evento (partida a frio,
      // item 3 da missão de correção): dinâmico, nunca hardcoded.
      const primeiroRegistro = [...this.sql.exec("SELECT MIN(ts) as t FROM pageviews_raw")][0]?.t || null;

      let visitantesAnterior = null, visualizacoesAnterior = null, dadosSuficientesComparacao = false;
      if (diasPeriodo) {
        // Período comparável = a MESMA janela deslocada N dias pra trás,
        // preservando a FRAÇÃO já decorrida (o período atual sempre tem um
        // "hoje" parcial; comparar contra uma janela anterior COMPLETA
        // distorceria a variação pra baixo). Regra generalizada em
        // 2026-09-27 — antes só "Hoje" fazia isso; 7d/30d comparavam
        // janela parcial contra janela cheia.
        const deslocamento = diasPeriodo * 86400000;
        const desdeAnteriorTs = desdeTs - deslocamento;
        const ateAnteriorTs = agora - deslocamento;
        const desdeAnteriorStr = new Date(desdeAnteriorTs).toISOString().slice(0, 10);
        dadosSuficientesComparacao = !!primeiroRegistro && primeiroRegistro <= desdeAnteriorTs;
        if (dadosSuficientesComparacao) {
          visitantesAnterior = ehHoje
            ? ([...this.sql.exec(
                "SELECT COUNT(DISTINCT session_id) as c FROM pageviews_raw WHERE ts >= ? AND ts < ?", desdeAnteriorTs, ateAnteriorTs
              )][0]?.c || 0)
            : ([...this.sql.exec(
                "SELECT COUNT(DISTINCT session_id) as c FROM visit_days WHERE day >= ? AND day < ?", desdeAnteriorStr, desdeStr
              )][0]?.c || 0);
          visualizacoesAnterior = [...this.sql.exec(
            "SELECT COUNT(*) as c FROM pageviews_raw WHERE ts >= ? AND ts < ?", desdeAnteriorTs, ateAnteriorTs
          )][0]?.c || 0;
        }
      }

      return new Response(JSON.stringify({
        periodo, visitantes, visualizacoes, recorrentes, eventos, topPaths, origens, dispositivos,
        dadosDesde: primeiroRegistro,
        janelaIncompleta: !!primeiroRegistro && primeiroRegistro > desdeTs,
        comparacao: dadosSuficientesComparacao ? { visitantesAnterior, visualizacoesAnterior } : null
      }), { headers: { "Content-Type": "application/json" } });
    }

    /* Pronta para quando "Mais Lidas" for exibido — sem rota pública
       apontando pra cá nesta rodada. */
    if (request.method === "GET" && url.pathname === "/top") {
      // Command Center (2026-09-26): antes só aceitava 24 ou 168 (fixo,
      // usado pelo Mais Lidas); agora aceita qualquer janela até a
      // retenção máxima de "views" (RETENCAO_PAGEVIEW_MS, 8 dias =
      // 192h) — Command Center usa isso pra "Conteúdo" por período.
      const janelaHoras = Math.min(Math.max(parseInt(url.searchParams.get("horas") || "24", 10) || 24, 1), 192);
      const limite = Math.min(parseInt(url.searchParams.get("limite") || "10", 10) || 10, 50);
      const desde = Date.now() - janelaHoras * 3600000;
      const cursor = this.sql.exec(
        "SELECT article_id, COUNT(*) as views FROM views WHERE ts > ? GROUP BY article_id ORDER BY views DESC LIMIT ?",
        desde, limite
      );
      return new Response(JSON.stringify({ janelaHoras, itens: [...cursor] }), {
        headers: { "Content-Type": "application/json" }
      });
    }

    if (request.method === "GET" && url.pathname === "/historico") {
      const dias = Math.min(Math.max(parseInt(url.searchParams.get("dias") || "7", 10), 1), 65);
      const desde = Date.now() - dias * 86400000;
      const cursor = this.sql.exec(
        "SELECT substr(datetime(ts/1000,'unixepoch'),1,10) as dia, COUNT(DISTINCT session_id) as visitantes, COUNT(*) as visualizacoes FROM pageviews_raw WHERE ts >= ? GROUP BY dia ORDER BY dia ASC",
        desde
      );
      return new Response(JSON.stringify({ dias, dados: [...cursor] }), {
        headers: { "Content-Type": "application/json" }
      });
    }

    return new Response("not found", { status: 404 });
  }

  async alarm() {
    this.sql.exec("DELETE FROM views WHERE ts < ?", Date.now() - RETENCAO_PAGEVIEW_MS);
    // "visit_days" (Command Center, 2026-09-26): retenção estendida de 3
    // pra 65 dias — precisa cobrir a janela de 30 dias MAIS o período
    // anterior de 30 dias usado na comparação "vs período comparável".
    // "totals" (o acumulado real) nunca é tocado aqui.
    const limiteDias = new Date(Date.now() - RETENCAO_COMMAND_CENTER_MS).toISOString().slice(0, 10);
    this.sql.exec("DELETE FROM visit_days WHERE day < ?", limiteDias);
    this.sql.exec("DELETE FROM pageviews_raw WHERE ts < ?", Date.now() - RETENCAO_COMMAND_CENTER_MS);
    this.sql.exec("DELETE FROM events WHERE ts < ?", Date.now() - RETENCAO_COMMAND_CENTER_MS);
    await this.state.storage.setAlarm(Date.now() + 3600000);
  }
}

/* =========================================================================
   PESQUISA SALARIAL — Durable Object SQLite (2026-10-03)
   Armazena respostas anônimas da /pesquisa-salarial. Sem PII: nome, CPF,
   e-mail ou identificador pessoal nunca entram. IP é convertido em hash
   de 8 bytes (SHA-256 + salt fixo) antes de chegar aqui — nunca o IP bruto.
   Rate limit: 3 respostas por IP por hora. Limpeza automática de dados de
   rate-limit mais antigos que 24 horas.
   Estatísticas só liberadas quando n ≥ 10 para uma função específica.
========================================================================= */
export class PesquisaSalarial {
  constructor(state, env) {
    this.state = state;
    this.sql = state.storage.sql;
    this._ok = false;
  }
  _setup() {
    if (this._ok) return;
    this.sql.exec(
      'CREATE TABLE IF NOT EXISTS respostas (' +
      ' id INTEGER PRIMARY KEY AUTOINCREMENT,' +
      ' created_at INTEGER NOT NULL,' +
      ' funcao_slug TEXT NOT NULL,' +
      ' funcao_outro TEXT,' +
      ' experiencia_faixa TEXT NOT NULL,' +
      ' tipo_unidade TEXT NOT NULL,' +
      ' escala TEXT,' +
      ' vinculo TEXT NOT NULL,' +
      ' salario_base_faixa TEXT NOT NULL,' +
      ' remuneracao_total_faixa TEXT NOT NULL,' +
      ' adicionais TEXT,' +
      ' estado TEXT,' +
      ' ip_hash TEXT NOT NULL' +
      ');'
    );
    this.sql.exec(
      'CREATE TABLE IF NOT EXISTS rl (' +
      ' ip_hash TEXT NOT NULL,' +
      ' janela INTEGER NOT NULL,' +
      ' cnt INTEGER NOT NULL DEFAULT 0,' +
      ' PRIMARY KEY (ip_hash, janela)' +
      ');'
    );
    this._ok = true;
  }
  async fetch(request) {
    this._setup();
    const u = new URL(request.url);
    if (request.method === 'POST' && u.pathname === '/inserir') return this._inserir(request);
    if (request.method === 'GET' && u.pathname.startsWith('/stats/')) return this._stats(u.pathname.slice(7));
    return new Response('nf', { status: 404 });
  }
  async _inserir(request) {
    let d;
    try { d = await request.json(); } catch (_e) { return _jsonResp({ ok: false, erro: 'json' }, 400); }
    const ipHash = (typeof d._ipHash === 'string' && /^[0-9a-f]{16}$/.test(d._ipHash)) ? d._ipHash : 'unknown';
    const agora = Date.now();
    const janela = Math.floor(agora / 3600000);
    // Rate limit
    const rl = this.sql.exec('SELECT cnt FROM rl WHERE ip_hash=? AND janela=?', ipHash, janela).toArray();
    if (rl.length && rl[0].cnt >= 3) return _jsonResp({ ok: false, erro: 'rate_limit' }, 429);
    if (rl.length) {
      this.sql.exec('UPDATE rl SET cnt=cnt+1 WHERE ip_hash=? AND janela=?', ipHash, janela);
    } else {
      this.sql.exec('INSERT INTO rl (ip_hash,janela,cnt) VALUES (?,?,1)', ipHash, janela);
      this.sql.exec('DELETE FROM rl WHERE janela<?', janela - 24);
    }
    // Validar
    const EXP = new Set(['menos-1-ano','1-3-anos','3-5-anos','5-10-anos','mais-10-anos']);
    const UNI = new Set(['fpso','sonda','plataforma','embarcacao','apoio-maritimo','rov','outro']);
    const VIN = new Set(['clt','pj','temporario','outro']);
    const FB  = new Set(['ate-3000','3000-5000','5000-8000','8000-12000','12000-18000','18000-25000','acima-25000']);
    const FT  = new Set(['ate-5000','5000-8000','8000-12000','12000-18000','18000-25000','25000-35000','35000-50000','acima-50000']);
    const ADI_OK = new Set(['periculosidade','confinamento','embarque','produtividade-plr','hora-extra','nenhum']);
    if (!EXP.has(d.experiencia_faixa)) return _jsonResp({ ok: false, erro: 'campo' }, 400);
    if (!UNI.has(d.tipo_unidade))       return _jsonResp({ ok: false, erro: 'campo' }, 400);
    if (!VIN.has(d.vinculo))            return _jsonResp({ ok: false, erro: 'campo' }, 400);
    if (!FB.has(d.salario_base_faixa))  return _jsonResp({ ok: false, erro: 'campo' }, 400);
    if (!FT.has(d.remuneracao_total_faixa)) return _jsonResp({ ok: false, erro: 'campo' }, 400);
    const slug = (typeof d.funcao_slug === 'string' && d.funcao_slug.length <= 60) ? d.funcao_slug : 'outro';
    const outro = (slug === 'outro' && typeof d.funcao_outro === 'string') ? d.funcao_outro.slice(0, 80) : null;
    const escala = (typeof d.escala === 'string' && ['14x14','14x21','21x21','28x28','outro'].includes(d.escala)) ? d.escala : null;
    const adi = Array.isArray(d.adicionais) ? JSON.stringify(d.adicionais.filter(a => ADI_OK.has(a)).slice(0, 6)) : '[]';
    const est = (typeof d.estado === 'string' && d.estado.length <= 5) ? d.estado : null;
    this.sql.exec(
      'INSERT INTO respostas (created_at,funcao_slug,funcao_outro,experiencia_faixa,tipo_unidade,escala,vinculo,salario_base_faixa,remuneracao_total_faixa,adicionais,estado,ip_hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',
      agora, slug, outro, d.experiencia_faixa, d.tipo_unidade, escala, d.vinculo,
      d.salario_base_faixa, d.remuneracao_total_faixa, adi, est, ipHash
    );
    return _jsonResp({ ok: true });
  }
  _stats(slug) {
    const MINIMO = 10;
    const rows = this.sql.exec(
      'SELECT salario_base_faixa,remuneracao_total_faixa,experiencia_faixa FROM respostas WHERE funcao_slug=? ORDER BY created_at DESC LIMIT 500',
      slug
    ).toArray();
    const n = rows.length;
    if (n < MINIMO) return _jsonResp({ n, suficiente: false });
    const MPB = { 'ate-3000':2500,'3000-5000':4000,'5000-8000':6500,'8000-12000':10000,'12000-18000':15000,'18000-25000':21500,'acima-25000':28000 };
    const MPT = { 'ate-5000':4000,'5000-8000':6500,'8000-12000':10000,'12000-18000':15000,'18000-25000':21500,'25000-35000':30000,'35000-50000':42500,'acima-50000':55000 };
    function med(arr) { if (!arr.length) return null; const s=[...arr].sort((a,b)=>a-b); const m=Math.floor(s.length/2); return s.length%2?s[m]:Math.round((s[m-1]+s[m])/2); }
    function pct(arr,p) { const s=[...arr].sort((a,b)=>a-b); return s[Math.max(0,Math.floor(p*s.length)-1)]; }
    const vb = rows.map(r=>MPB[r.salario_base_faixa]).filter(Boolean);
    const vt = rows.map(r=>MPT[r.remuneracao_total_faixa]).filter(Boolean);
    const expCnt = {}; rows.forEach(r=>{ expCnt[r.experiencia_faixa]=(expCnt[r.experiencia_faixa]||0)+1; });
    const expPred = Object.entries(expCnt).sort((a,b)=>b[1]-a[1])[0]?.[0]||null;
    const mes = new Date().toLocaleString('pt-BR', { month: 'short', year: 'numeric' }).replace('.','');
    return _jsonResp({
      n, suficiente: true,
      medianaBase: med(vb), p25Base: pct(vb,0.25), p75Base: pct(vb,0.75),
      medianaTotal: med(vt), p25Total: pct(vt,0.25), p75Total: pct(vt,0.75),
      expPredominante: expPred, atualizadoEm: mes
    });
  }
}
function _jsonResp(obj, status) {
  return new Response(JSON.stringify(obj), { status: status || 200, headers: { 'Content-Type': 'application/json' } });
}

/* =========================================================================
   OWNEWS COMMAND CENTER (2026-09-26) — painel privado do proprietário.
   NUNCA público, NUNCA indexado, NUNCA linkado da navegação pública.
   Autenticação server-side por senha (Worker secret CC_PASSWORD, nunca
   hardcoded) + cookie de sessão assinado com HMAC-SHA256 (Worker secret
   CC_SESSION_SECRET) — nunca confia só em JavaScript/frontend. Dados
   vêm de fontes JÁ existentes no projeto (Durable Object PageViews
   estendido acima, coletor shrill-pond-a915 já público, Supabase já
   usado em toda a Home) — nenhum serviço/SDK externo novo instalado
   nesta rodada. GA4/Search Console/Cloudflare Analytics/AdSense exigem
   credencial nova (token/OAuth) — ficam como "Conexão pendente",
   documentado em detalhe no MISSION-STATE. ========================= */

async function ccAssinar(valor, segredo) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey("raw", enc.encode(segredo), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const assinatura = await crypto.subtle.sign("HMAC", key, enc.encode(valor));
  return btoa(String.fromCharCode(...new Uint8Array(assinatura))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

async function ccCriarSessao(env) {
  const expira = Date.now() + 30 * 24 * 3600000;
  const valor = String(expira);
  const assinatura = await ccAssinar(valor, env.CC_SESSION_SECRET);
  return valor + "." + assinatura;
}

async function ccValidarSessao(cookieValor, env) {
  if (!cookieValor || !env.CC_SESSION_SECRET) return false;
  const partes = cookieValor.split(".");
  if (partes.length !== 2) return false;
  const [valor, assinatura] = partes;
  const expira = parseInt(valor, 10);
  if (!Number.isFinite(expira) || expira < Date.now()) return false;
  const esperada = await ccAssinar(valor, env.CC_SESSION_SECRET);
  // Comparação de tamanho fixo simples — risco de timing attack aqui é
  // desprezível (não é comparação de senha, é verificação de assinatura
  // de uma sessão já emitida) mas usamos o mesmo padrão defensivo.
  if (assinatura.length !== esperada.length) return false;
  let diff = 0;
  for (let i = 0; i < assinatura.length; i++) diff |= assinatura.charCodeAt(i) ^ esperada.charCodeAt(i);
  return diff === 0;
}

function ccLerCookie(request) {
  const cabecalho = request.headers.get("Cookie") || "";
  const m = cabecalho.match(/(?:^|;\s*)cc_session=([^;]+)/);
  return m ? decodeURIComponent(m[1]) : null;
}

async function ccAutenticado(request, env) {
  if (!env.CC_SESSION_SECRET) return false;
  return ccValidarSessao(ccLerCookie(request), env);
}

// Rate-limit de tentativas de login — reaproveita o KV já existente
// (PERGUNTE_IA_KV) em vez de criar um recurso novo, com um prefixo de
// chave próprio. Nunca guarda a senha, só a contagem de falhas por IP.
async function ccRateLimitOk(request, env) {
  if (!env.PERGUNTE_IA_KV) return true;
  const ip = request.headers.get("CF-Connecting-IP") || "desconhecido";
  const atual = parseInt((await env.PERGUNTE_IA_KV.get("cc_login_falhas:" + ip)) || "0", 10);
  return atual < 10;
}
async function ccRegistrarFalhaLogin(request, env) {
  if (!env.PERGUNTE_IA_KV) return;
  const ip = request.headers.get("CF-Connecting-IP") || "desconhecido";
  const chave = "cc_login_falhas:" + ip;
  const atual = parseInt((await env.PERGUNTE_IA_KV.get(chave)) || "0", 10);
  await env.PERGUNTE_IA_KV.put(chave, String(atual + 1), { expirationTtl: 3600 });
}


