    // ── Checkpoint 4: Cruzar — JWT validation helper ────────────────────────
    async function cruzarValidarJWT(env, authHeader) {
      if (!authHeader || !authHeader.startsWith('Bearer ')) return null;
      const SUPA = 'https://awyowuhwkqfyhwgdpepp.supabase.co';
      const SUPA_KEY = 'sb_publishable_9cRatirjls8SQIoHdTUkLQ_8jt6psGt';
      try {
        const r = await fetch(SUPA + '/auth/v1/user', {
          headers: { 'Authorization': authHeader, 'apikey': SUPA_KEY }
        });
        if (!r.ok) return null;
        const d = await r.json();
        return d.id ? d : null;
      } catch { return null; }
    }

    // Invite info (public — no JWT)
    if (url.pathname === '/api/cruzar/invite-info' && request.method === 'GET') {
      if (!env.PERGUNTE_IA_KV) return Response.json({ ok: false, erro: 'KV indisponível' }, { status: 503 });
      const token = url.searchParams.get('token');
      if (!token || token.length < 8) return Response.json({ ok: false, erro: 'Token inválido' }, { status: 400 });
      const raw = await env.PERGUNTE_IA_KV.get('cruzar_invite:' + token);
      if (!raw) return Response.json({ ok: false, erro: 'Convite inválido ou expirado' }, { status: 404 });
      const inv = JSON.parse(raw);
      return Response.json({ ok: true, from_nome: inv.from_nome });
    }

    // Criar convite
    if (url.pathname === '/api/cruzar/invite' && request.method === 'POST') {
      if (!env.PERGUNTE_IA_KV) return Response.json({ ok: false, erro: 'KV indisponível' }, { status: 503 });
      const user = await cruzarValidarJWT(env, request.headers.get('Authorization'));
      if (!user) return Response.json({ ok: false, erro: 'Não autenticado' }, { status: 401 });
      let body; try { body = await request.json(); } catch { body = {}; }
      const nome = (body.nome || (user.user_metadata && user.user_metadata.full_name) || 'Companheiro(a)').slice(0, 60);
      const token = crypto.randomUUID().replace(/-/g, '');
      const data = { from_user_id: user.id, from_nome: nome, from_escala: body.escala_config || null, created_at: new Date().toISOString() };
      await env.PERGUNTE_IA_KV.put('cruzar_invite:' + token, JSON.stringify(data), { expirationTtl: 172800 });
      await env.PERGUNTE_IA_KV.put('cruzar_invite_owner:' + user.id, token, { expirationTtl: 172800 });
      return Response.json({ ok: true, token, link: 'https://ownews.com.br/minha-escala?convite=' + token });
    }

    // Aceitar convite
    if (url.pathname === '/api/cruzar/accept' && request.method === 'POST') {
      if (!env.PERGUNTE_IA_KV) return Response.json({ ok: false, erro: 'KV indisponível' }, { status: 503 });
      const user = await cruzarValidarJWT(env, request.headers.get('Authorization'));
      if (!user) return Response.json({ ok: false, erro: 'Não autenticado' }, { status: 401 });
      let body; try { body = await request.json(); } catch { return Response.json({ ok: false, erro: 'Body inválido' }, { status: 400 }); }
      const { token, escala_config: ecfgB, nome: nomeB } = body;
      if (!token) return Response.json({ ok: false, erro: 'Token obrigatório' }, { status: 400 });
      const raw = await env.PERGUNTE_IA_KV.get('cruzar_invite:' + token);
      if (!raw) return Response.json({ ok: false, erro: 'Convite inválido ou expirado' }, { status: 404 });
      const inv = JSON.parse(raw);
      if (inv.from_user_id === user.id) return Response.json({ ok: false, erro: 'Você não pode aceitar seu próprio convite' }, { status: 400 });
      const nomeB2 = (nomeB || (user.user_metadata && user.user_metadata.full_name) || 'Companheiro(a)').slice(0, 60);
      const now = new Date().toISOString();
      await env.PERGUNTE_IA_KV.put('cruzar_conn:' + inv.from_user_id, JSON.stringify({ partner_id: user.id, partner_nome: nomeB2, escala_config: ecfgB, connected_at: now }));
      await env.PERGUNTE_IA_KV.put('cruzar_conn:' + user.id, JSON.stringify({ partner_id: inv.from_user_id, partner_nome: inv.from_nome, escala_config: inv.from_escala, connected_at: now }));
      await env.PERGUNTE_IA_KV.delete('cruzar_invite:' + token);
      await env.PERGUNTE_IA_KV.delete('cruzar_invite_owner:' + inv.from_user_id);
      return Response.json({ ok: true, from_nome: inv.from_nome });
    }

    // Buscar config do parceiro
    if (url.pathname === '/api/cruzar/partner' && request.method === 'GET') {
      if (!env.PERGUNTE_IA_KV) return Response.json({ ok: false, erro: 'KV indisponível' }, { status: 503 });
      const user = await cruzarValidarJWT(env, request.headers.get('Authorization'));
      if (!user) return Response.json({ ok: false, erro: 'Não autenticado' }, { status: 401 });
      const raw = await env.PERGUNTE_IA_KV.get('cruzar_conn:' + user.id);
      if (!raw) return Response.json({ ok: false, erro: 'Sem conexão ativa' }, { status: 404 });
      const conn = JSON.parse(raw);
      return Response.json({ ok: true, partner_nome: conn.partner_nome, escala_config: conn.escala_config, connected_at: conn.connected_at });
    }

    // Desconectar
    if (url.pathname === '/api/cruzar/disconnect' && request.method === 'POST') {
      if (!env.PERGUNTE_IA_KV) return Response.json({ ok: false, erro: 'KV indisponível' }, { status: 503 });
      const user = await cruzarValidarJWT(env, request.headers.get('Authorization'));
      if (!user) return Response.json({ ok: false, erro: 'Não autenticado' }, { status: 401 });
      const raw = await env.PERGUNTE_IA_KV.get('cruzar_conn:' + user.id);
      if (raw) {
        const conn = JSON.parse(raw);
        await env.PERGUNTE_IA_KV.delete('cruzar_conn:' + user.id);
        if (conn.partner_id) await env.PERGUNTE_IA_KV.delete('cruzar_conn:' + conn.partner_id);
      }
      const pending = await env.PERGUNTE_IA_KV.get('cruzar_invite_owner:' + user.id);
      if (pending) {
        await env.PERGUNTE_IA_KV.delete('cruzar_invite:' + pending);
        await env.PERGUNTE_IA_KV.delete('cruzar_invite_owner:' + user.id);
      }
      return Response.json({ ok: true });
    }

    // Etapa 6 (2026-09-24) — API do "Pergunte ao OWNews". POST only, JSON.
